custom_css:
/* --- ひだまり Theme https://discord.com/channels/1291925535324110879/1380392618336194702
感谢美化楼的老师。类名，输入框伪提示词来自尾老师，hy老师去除思维链箭头，12老师的去除思维链阴影，以及na老师的悬浮底栏和思维链文字自定义，楼层信息自定义--- */

/* --- 1. 字体导入 --- */
@import url('https://fonts.googleapis.com/css2?family=Caveat:wght@400;700&display=swap'); /* 英文手写: Caveat */
@import url("https://fontsapi.zeoseven.com/253/main/result.css"); /* 全局中文: JasonHandwriting1 */
@import url("https://fontsapi.zeoseven.com/61/main/result.css"); /* 代码: 851tegakizatsu */
@import url("https://fontsapi.zeoseven.com/993/main/result.css"); /* 引用: LXGW Bright */
@import url("https://fontsapi.zeoseven.com/2/main/result.css"); /* 标题: LXGW ZhenKai GB */

/* --- 2. 核心颜色与样式变量 --- */
:root {
    --theme-bg: #0A0F1A; /* 深海蓝/纯黑背景 */
    --panel-bg-color: rgba(10, 15, 25, 0.85);
    --panel-bg-hover: rgba(15, 25, 35, 0.95);
    --card-bg: rgba(15, 22, 35, 0.9);
    --input-bg: rgba(5, 10, 15, 0.85);
    --text-main: #E0E6ED;
    --text-subtle: #8B9BB4;
    --border-color: rgba(0, 229, 255, 0.3);
    --accent-color: #00E5FF; /* 霓虹青/赛博蓝 */
    --selected-color: #00B0FF;
    --font-english: 'Caveat', cursive;
    --font-main: "JasonHandwriting1", var(--font-english);
    --font-quote: "LXGW Bright", var(--font-english);
    --font-code: "851tegakizatsu", monospace;
    --font-title: "LXGW ZhenKai GB", var(--font-english);
    --border-radius: 4px;
}

/* --- 3. 全局样式 (强制无边框无阴影) --- */
* { box-shadow: none !important; border-style: none !important; }
body { 
    background-color: var(--theme-bg) !important; 
    background-image: url('https://images.unsplash.com/photo-1542751371-adc38448a05e?q=80&w=2070&auto=format&fit=crop'); /* 深色电竞房背景 */
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
    color: var(--text-main); 
    font-family: var(--font-main); 
    font-weight: normal; 
}
#sheld, #character_view { background: transparent !important; margin: 0 auto !important; left: 0; right: 0; border: none !important; overflow: visible !important; }
#chat { background: transparent !important; align-items: center !important; padding-bottom: 120px !important; }
h1, h2, h3, h4, .standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-title); color: var(--text-main); font-weight: normal; }

/* --- 4. 顶部导航栏 & 挂件 --- */
#top-settings-holder { position:relative; background-color: var(--panel-bg-color); backdrop-filter: blur(8px); border: none; }

.drawer-icon.fa-fw::before { content: '' !important; font-size: 0 !important; }
.drawer-icon.fa-fw { width: 30px; height: 30px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: transform 0.3s ease; filter: brightness(1.1); }
.drawer-icon.fa-fw:hover { transform: scale(1.1); filter: drop-shadow(0 0 5px var(--accent-color)); }

/* 极简游戏/赛博风导航图标 */
.drawer-icon.fa-sliders, #ai-config-button .drawer-icon { background-image: url('https://api.iconify.design/lucide:settings-2.svg?color=%2300E5FF'); }
.drawer-icon.fa-plug, #sys-settings-button .drawer-icon { background-image: url('https://api.iconify.design/lucide:cpu.svg?color=%2300E5FF'); }
.drawer-icon.fa-font, #advanced-formatting-button .drawer-icon { background-image: url('https://api.iconify.design/lucide:monitor.svg?color=%2300E5FF'); }
.drawer-icon.fa-book-atlas, #WI-SP-button .drawer-icon { background-image: url('https://api.iconify.design/lucide:book-open.svg?color=%2300E5FF'); }
.drawer-icon.fa-user, #user-settings-button .drawer-icon { background-image: url('https://api.iconify.design/lucide:user-circle.svg?color=%2300E5FF'); }
.drawer-icon.fa-image, .drawer-icon.fa-panorama { background-image: url('https://api.iconify.design/lucide:image.svg?color=%2300E5FF'); }
.drawer-icon.fa-cubes, #extensions-settings-button .drawer-icon { background-image: url('https://api.iconify.design/lucide:blocks.svg?color=%2300E5FF'); }
.drawer-icon.fa-bars-progress, #table_database_settings_drawer .drawer-icon { background-image: url('https://api.iconify.design/lucide:database.svg?color=%2300E5FF'); }
.drawer-icon.fa-face-smile, #persona-management-button .drawer-icon { background-image: url('https://api.iconify.design/lucide:gamepad-2.svg?color=%2300E5FF'); }
.drawer-icon.fa-address-card, #character_popup_button .drawer-icon { background-image: url('https://api.iconify.design/lucide:contact.svg?color=%2300E5FF'); }

/* 抽屉背景图 */
.drawer-content { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260325/pJOG/1200X675/b607e37a91be1ba50acac1c5bb11efb4.jpg/webp'); background-size: cover; background-position: center; border: none !important; border-radius: var(--border-radius); }
.drawer-content::before { content:''; position:absolute; top:0; left:0; width:100%; height:100%; background:rgba(10,15,25,0.7); pointer-events:none; z-index:-1; }

/* --- 5. 底部悬浮输入栏 --- */
#send_textarea::placeholder { color: transparent !important; opacity: 0 !important; }
#send_textarea::-webkit-input-placeholder { color: transparent !important; opacity: 0 !important; }
#form_sheld { position: absolute !important; bottom: 15px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; }
#send_form { pointer-events: auto; width: 90% !important; max-width: 800px !important; margin: 0 auto !important; border-radius: 8px !important; background-color: var(--input-bg) !important; padding: 10px 15px !important; backdrop-filter: blur(10px) !important; -webkit-backdrop-filter: blur(10px) !important; transition: all 0.5s ease !important; position: relative; border-style: none !important; }
#send_form:hover { transform: translateY(-3px) !important; background-color: rgba(15, 25, 35, 0.95) !important; }
#rightSendForm, #leftSendForm { gap: 10px; }
#send_textarea { clip-path: none !important; border: none !important; background: transparent !important; color: var(--text-main) !important; }

/* 网吧沉浸式伪提示词 */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { 
    content: '隐れ家'; 
    color: var(--text-subtle); 
    position: absolute; 
    top: 50%; left: 50%; 
    transform: translate(-50%, -50%); 
    font-family: var(--font-quote); 
    font-size: 0.5em; 
    pointer-events: none; 
    z-index: 10; 
    white-space: nowrap; 
    letter-spacing: 2px; 
}

#options_button::before, #send_but::before, #send_form #extensionsMenuButton::before, #ai_retry_button::before, #auto_completion_button::before { display: none !important; }
#options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button { width: 30px; height: 30px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: transform 0.2s ease; font-size: 0; border: none; background-color: transparent; }
#options_button:hover, #send_but:hover, #send_form #extensionsMenuButton:hover, #ai_retry_button:hover, #auto_completion_button:hover { transform: scale(1.1); filter: drop-shadow(0 0 5px var(--accent-color)); }

/* 极简底栏图标 */
#options_button { background-image: url('https://api.iconify.design/lucide:menu.svg?color=%2300E5FF'); }
#send_form #extensionsMenuButton { background-image: url('https://api.iconify.design/lucide:puzzle.svg?color=%2300E5FF'); }
#send_but { background-image: url('https://api.iconify.design/lucide:send.svg?color=%2300E5FF'); }
#ai_retry_button { background-image: url('https://api.iconify.design/lucide:refresh-cw.svg?color=%2300E5FF'); }
#auto_completion_button { background-image: url('https://api.iconify.design/lucide:sparkles.svg?color=%2300E5FF'); }

/* --- 6. 核心：消息卡片布局与样式 --- */
.mes { 
    display: flex; flex-direction: column; 
    padding: 0 !important; 
    margin: 40px auto 85px !important; /* 增加了底部间距以容纳气泡 */
    width: 85%; max-width: 800px; 
    backdrop-filter: blur(12px) !important;
    -webkit-backdrop-filter: blur(12px) !important;
    border-style: none !important; 
    border-radius: 8px !important; 
    overflow: visible !important; 
    position: relative; 
}
.mes[is_user="true"] { background: rgba(15, 22, 35, 0.7) !important; } 
.mes[is_user="false"] { background: rgba(10, 18, 30, 0.8) !important; }

/* 顶部横幅图区 */
.mes .mesAvatarWrapper {
    display: flex; justify-content: flex-start; align-items: center; padding: 0;
    width: 100%;
    background-size: cover; background-position: center;
    position: relative; z-index: 5;
    height: 180px !important; 
    min-height: 180px !important;
    overflow: visible !important;
    border-radius: 8px 8px 0 0;
    margin-bottom: 0 !important; 
}
.mes .mesAvatarWrapper::before { display: none; }

/* AI与User通用顶部贴图 */
.mes[is_user="true"] .mesAvatarWrapper, .mes[is_user="false"] .mesAvatarWrapper { 
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260324/kTzl/4578X2298/_cgi-bin_mmwebwx-bin_webwxgetmsgimg__%26MsgID%3D1996826756721333558%26skey%3D%40crypt_5a237c93_0f4a0868fb274efb7981ead6145fd559%26mmweb_appid%3Dwx_webfilehelper.jpg/webp') !important; 
}

/* 横幅右侧的悬浮小票贴纸 - 放大 */
.mes .mesAvatarWrapper::after {
    content: '';
    position: absolute;
    top: -15px;
    right: 2%; 
    width: 180px; 
    height: 280px; 
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260324/VxdH/800X2000/%E8%93%9D%E7%81%B0%E8%89%B2%E7%A9%BA%E6%B0%94%E5%87%80%E5%8C%96%E5%99%A8%E7%8E%B0%E4%BB%A3%E7%A7%91%E6%8A%80%E4%BF%83%E9%94%80%E4%B8%AD%E6%96%87%E6%89%8B%E6%9C%BA%E7%94%B5%E5%95%86%E8%AF%A6%E6%83%85%E9%A1%B5_%281%29.png/webp');
    background-size: contain;
    background-repeat: no-repeat;
    background-position: top center;
    z-index: 40; 
    pointer-events: none;
    transform: rotate(3deg);
    filter: drop-shadow(3px 6px 12px rgba(0,0,0,0.6));
}

/* 网页窗口化头像 - AI与用户统一在左侧 */
.mes .avatar {
    position: absolute;
    top: 50%; 
    left: 25px !important; 
    right: auto !important;
    transform: translateY(-50%) !important;
    width: 110px; height: 110px; 
    background-color: #0A0F1A !important;
    border-style: solid !important;
    border-width: 1px 1px 1px 1px !important;
    border-color: #2D3748 !important;
    border-top: 22px solid #2D3748 !important; /* 伪装浏览器顶部栏 */
    padding: 0 !important; 
    z-index: 30; 
    display: flex !important; 
    align-items: center;
    justify-content: center;
    border-radius: 6px !important;
    box-shadow: none !important; 
    overflow: visible !important; 
}
/* 浏览器红黄绿三个小按钮 */
.mes .avatar::before {
    content: '';
    position: absolute;
    top: -15px;
    left: 6px;
    width: 8px; height: 8px;
    border-radius: 50%;
    background: #FF5F56;
    box-shadow: 14px 0 0 #FFBD2E, 28px 0 0 #27C93F !important;
    z-index: 31;
}
.mes .avatar img { width: 100% !important; height: 100% !important; object-fit: cover !important; border-radius: 0 0 4px 4px !important; border: none !important; }

/* 正文区域 */
.mes .mes_block { background-color: transparent !important; background-image: none !important; padding: 15px 25px 30px 25px !important; margin-top: 0 !important; position: relative; border: none !important; overflow: visible !important; min-height: 80px !important; width: 100% !important; box-sizing: border-box !important; }
.mes .mes_text, .mes_reasoning { background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important; backdrop-filter: none !important; }

/* 思维链 - 网吧系统检索样式 */
#chat .mes .mes_reasoning_header { background: transparent !important; border: none !important; border-radius: 0; backdrop-filter: none !important; padding: 0 !important; margin-bottom: 10px !important; display: inline-flex !important; align-items: center !important; }
.mes_reasoning_arrow { display: none !important; }
.mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; }
.mes_reasoning_header h4::before, .mes_reasoning_header_title::before { content: "[ 系统数据检索中... ]"; font-family: var(--font-title); font-size: 0.9em; color: var(--accent-color); visibility: visible; letter-spacing: 2px; text-shadow: 0 0 5px rgba(0,229,255,0.4); }
.mes_reasoning { border-left: 2px dashed var(--accent-color) !important; padding-left: 15px !important; margin-bottom: 20px !important; color: var(--text-subtle); }
.mes .mes_text { line-height: 1.8; color: var(--text-main); font-size: 15px; }

/* --- 排版与文字特效系统 --- */
.mes_text h1 { font-family: var(--font-title); color: var(--accent-color); font-size: 1.6em; text-align: left; padding-bottom: 10px; margin: 30px 0 20px 0; border-bottom: 1px solid rgba(0,229,255,0.2) !important; font-weight: normal; letter-spacing: 2px; text-transform: uppercase; }
.mes_text h2 { font-family: var(--font-title); color: var(--text-main); font-size: 1.3em; padding: 4px 0 4px 15px; border-left: 4px solid var(--accent-color) !important; margin: 25px 0 15px 0; background: linear-gradient(to right, rgba(0, 229, 255, 0.1) 0%, transparent 100%); font-weight: normal; }
.mes_text em, .mes_text i { font-family: var(--font-quote); font-style: normal !important; color: var(--accent-color); }
.mes_text strong, .mes_text b { font-family: var(--font-title); color: #fff; font-weight: normal; text-shadow: 0 0 3px rgba(0,229,255,0.5); }
.mes_text blockquote { background-color: rgba(10, 15, 25, 0.5); border-style: none !important; border-left: 3px solid var(--accent-color) !important; padding: 12px 18px; margin: 18px 0; font-family: var(--font-quote); color: var(--quote_text_color); }
.mes_text span.quote, .mes_text q, .mes_text .dialogue { font-family: var(--font-quote); color: var(--quote_text_color); }
.mes_text code { font-family: var(--font-code); background-color: rgba(0, 229, 255, 0.1) !important; color: var(--accent-color) !important; padding: 2px 6px; border-radius: 2px; border: 1px solid rgba(0,229,255,0.2) !important; border-style: solid !important; }

/* --- 楼层信息、名字 --- */
.mes .mesAvatarWrapper > .ch_name { display: none !important; }
.mes .mes_block > .ch_name { display: flex !important; position: relative !important; top: auto !important; left: auto !important; right: auto !important; width: 100% !important; align-items: center !important; background: transparent !important; border: none !important; z-index: 100; transform: none !important; padding: 0 0 10px 0 !important; margin: 0 0 15px 0 !important; border-bottom: 1px solid rgba(0, 229, 255, 0.2) !important; }
.mes[is_user="false"] .ch_name, .mes[is_user="true"] .ch_name { justify-content: flex-start !important; }
.mes .ch_name > .flex-container { display: flex !important; align-items: center !important; gap: 10px !important; flex-wrap: wrap !important; }
.mes .ch_name .name_text { font-family: var(--font-title); font-size: 1.2em; color: var(--accent-color) !important; text-shadow: none !important; }
.mes .mesIDDisplay, .mes .mes_timer { position: static !important; color: #667788 !important; font-size: 0.8em; line-height: 1 !important; transform: none !important; }

/* 悬浮侧边工具栏 */
.mes .mes_buttons, .mes .mes_edit_buttons { flex-direction: row-reverse; gap: 8px; position: static !important; opacity: 0.3; transition: opacity 0.3s ease; pointer-events: auto !important; }
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons { opacity: 1; }
.mes .mes_buttons .mes_button, .mes .mes_edit_buttons .mes_button { background-color: rgba(10, 15, 25, 0.8) !important; backdrop-filter: blur(4px); color: var(--accent-color) !important; padding: 6px !important; border-radius: 4px !important; cursor: pointer; transition: all 0.2s ease; font-size: 0.9em; height: auto !important; width: auto !important; line-height: 1 !important; border-style: none !important; }
.mes .mes_buttons .mes_button:hover, .mes .mes_edit_buttons .mes_button:hover { background-color: var(--accent-color) !important; color: #000 !important; }

/* 打字提示器 */
#typing_indicator { background-image: url('https://api.iconify.design/lucide:loader.svg?color=%2300E5FF') !important; background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; animation: spin 1.5s linear infinite; border: none !important; height: 35px !important; width: 35px !important; margin: 10px auto !important; }
#typing_indicator .dot { display: none !important; }
@keyframes spin { 100% { transform: rotate(360deg); } }

/* --- 7. 网吧语境小气泡 --- */
/* AI/网管发言气泡 */
.mes[is_user="false"]::after {
    content: '「ごゆっくりどうぞ。」 - 店長';
    position: absolute;
    bottom: -32px;
    left: 25px;
    background: rgba(10, 18, 30, 0.95);
    border: 1px solid rgba(0, 229, 255, 0.4);
    color: var(--text-subtle);
    padding: 4px 12px;
    border-radius: 0 10px 10px 10px;
    font-size: 13px;
    font-family: var(--font-main);
    box-shadow: 2px 2px 5px rgba(0,0,0,0.5);
    z-index: 10;
    pointer-events: none;
}

/* 用户发言气泡 */
.mes[is_user="true"]::after {
    content: '「３時間延長お願いします。」 - お客様';
    position: absolute;
    bottom: -32px;
    right: 25px;
    background: rgba(15, 22, 35, 0.95);
    border: 1px solid rgba(139, 155, 180, 0.4);
    color: var(--text-subtle);
    padding: 4px 12px;
    border-radius: 10px 0 10px 10px;
    font-size: 13px;
    font-family: var(--font-main);
    box-shadow: -2px 2px 5px rgba(0,0,0,0.5);
    z-index: 10;
    pointer-events: none;
}

/* 用户模拟机号气泡 (位于发言气泡下方) */
.mes[is_user="true"]::before {
    content: 'TERMINAL No.04 [稼働中]';
    position: absolute;
    bottom: -62px;
    right: 25px;
    background: rgba(0, 229, 255, 0.05);
    border: 1px dotted var(--accent-color);
    color: var(--accent-color);
    padding: 3px 12px;
    border-radius: 4px;
    font-size: 11px;
    font-family: var(--font-english);
    letter-spacing: 1px;
    z-index: 10;
    pointer-events: none;
}

/* --- 全局UI设定 --- */
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, details > summary, #power-user-options-block h4, #InstructSettingsColumn h4, #SystemPromptColumn h4, #ContextSettings h4, .persona_management_global_settings h4, #character_popup h4, #AdvancedFormatting h4, #rm_group_chats_block h4, div[name*='HandlingToggles'] h4, div[name*='MiscellaneousToggles'] h4 { background: var(--card-bg) !important; border: none !important; border-radius: 4px !important; padding: 8px 12px !important; margin-bottom: 8px !important; color: var(--text-main) !important; }
input[type="text"], input[type="number"], input[type="search"], textarea, select, .text_pole { background-color: var(--input-bg) !important; border-style: none !important; color: var(--text-main) !important; border-radius: 4px !important; padding: 8px !important; border-bottom: 1px solid var(--border-color) !important; }
input:focus, textarea:focus, select:focus { outline: none !important; border-bottom: 1px solid var(--accent-color) !important; }
.menu_button { background-color: var(--card-bg) !important; border: none !important; color: var(--text-main) !important; transition: all 0.2s ease; border-radius: 4px !important; }
.menu_button:hover { background-color: rgba(0, 229, 255, 0.2) !important; color: var(--accent-color) !important; }
input[type="checkbox"]:checked::before { box-shadow: inset 1em 1em var(--accent-color) !important; }

/* 弹窗设计 */
dialog.popup { background-color: transparent !important; border: none !important; }
dialog.popup .popup-body, #dialogue_popup { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260325/iPeh/1200X800/fefcbd997e40a9b701ca118d09ea171b.jpg/webp') !important; background-size: cover !important; background-position: center !important; border: none !important; border-radius: var(--border-radius) !important; position: relative; overflow: hidden; }
dialog.popup .popup-body::before, #dialogue_popup::before { content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background-color: rgba(10, 15, 25, 0.85); z-index: 0; }
dialog.popup .popup-body > *, #dialogue_popup > * { position: relative; z-index: 1; }
.menu_button.active, .menu_button.world_set, .menu_button.fav_on { background-color: var(--selected-color) !important; color: #000 !important; }
#left-nav-panel .menu_button.selected { background-color: var(--selected-color) !important; color: #000 !important; }

/* 滑块设计 */
input[type="range"]::-webkit-slider-thumb { -webkit-appearance: none !important; appearance: none !important; width: 16px !important; height: 16px !important; background: var(--accent-color) !important; border-radius: 50% !important; cursor: pointer !important; }
input[type="range"]::-moz-range-thumb { width: 16px !important; height: 16px !important; background: var(--accent-color) !important; border-radius: 50% !important; border: none !important; cursor: pointer !important; }
.neo-range-slider { background: rgba(255, 255, 255, 0.1) !important; }

/* --- 自定义楼层信息 (赛博机位指示) --- */
.mes .mesIDDisplay {
    position: absolute;
    top: -25px !important; 
    background: rgba(10, 15, 25, 0.8) !important;
    border-style: none !important;
    border-bottom: 1px solid var(--accent-color) !important;
    color: var(--accent-color) !important; 
    font-size: 0.85em; 
    z-index: 100; 
    padding: 2px 10px !important;
    white-space: nowrap;
    line-height: 1 !important;
    border-radius: 4px 4px 0 0 !important;
    left: 20px !important;
    right: auto !important; 
    font-family: var(--font-english); 
    letter-spacing: 1px;
}
.mesIDDisplay::before { content: 'Terminal No. ' !important; color: var(--text-subtle); }
.mesIDDisplay::after { content: ' [Active]' !important; color: #27C93F; }

/* --- 手机端适配 --- */
@media (max-width: 768px) {
    .mes .avatar { left: 15px !important; width: 80px; height: 80px; border-top-width: 16px !important; }
    .mes .avatar::before { top: -11px; left: 4px; width: 6px; height: 6px; box-shadow: 10px 0 0 #FFBD2E, 20px 0 0 #27C93F !important; }
    .mes .mesAvatarWrapper::after { width: 130px; height: 210px; right: 0; }
    .mes .mes_block { padding: 10px 15px 20px 15px !important; }
    .mes[is_user="true"]::after, .mes[is_user="false"]::after, .mes[is_user="true"]::before { left: 15px; right: auto; transform: scale(0.85); transform-origin: left bottom; }
    .mes[is_user="true"]::after { right: 15px; left: auto; transform-origin: right bottom; }
    .mes[is_user="true"]::before { right: 15px; left: auto; transform-origin: right bottom; }
}

/* --- 删除确认等按钮框修正 --- */
#dialogue_popup { z-index: 10000 !important; pointer-events: auto !important; }
#dialogue_del_mes_ok, #dialogue_del_mes_cancel { display: inline-block !important; visibility: visible !important; opacity: 1 !important; position: relative !important; z-index: 10001 !important; background-color: rgba(20,30,45,0.8) !important; color: var(--text-main) !important; border: 1px solid rgba(0,229,255,0.3) !important; border-style: solid !important; border-radius: 4px !important; padding: 8px 16px !important; margin: 10px 5px !important; cursor: pointer !important; transition: all 0.2s ease !important; }
#dialogue_del_mes_ok:hover { background-color: #d32f2f !important; color: #fff !important; }
#dialogue_del_mes_cancel:hover { background-color: var(--accent-color) !important; color: #000 !important; }
.dialogue_popup_controls, #dialogue_popup .popup-buttons { display: flex !important; justify-content: center !important; gap: 15px !important; margin-top: 20px !important; pointer-events: auto !important; z-index: 10001 !important; }
